<?php
/** Cancel a mistaken open-period document through a balanced, auditable compensating document. */
function finance_correct(string $entity,int $entityId,string $date,string $reason,string $request,bool $restoreStock=false): int {
 global $pdo;domain_require('accounting.approve');domain_require('accounting.correct');$map=['expense'=>['expenses','expenses'],'loss'=>['expenses','losses'],'capital'=>['capital','capital'],'debt'=>['debts','debts']];if(!isset($map[$entity]))throw new InvalidArgumentException('Unsupported correction source.');[$table,$module]=$map[$entity];domain_require($module.'.approve');domain_consume_exact('accounting.correct');finance_date($date);$reason=trim($reason);if(mb_strlen($reason)<5||mb_strlen($reason)>500||!preg_match('/^[a-zA-Z0-9_-]{16,64}$/D',$request))throw new InvalidArgumentException(__t('Explain why this original document was mistaken.','دلیل اشتباه‌بودن سند اصلی را واضح بنویسید.','د اصلي سند تېروتنه روښانه کړئ.'));
 $hash=hash('sha256',json_encode([$entity,$entityId,$date,$reason,$restoreStock],JSON_THROW_ON_ERROR));
 return finance_atomic(function()use($pdo,$table,$entity,$entityId,$date,$reason,$request,$restoreStock,$hash){
  $q=$pdo->prepare("SELECT * FROM $table WHERE id=? AND shop_id=?".finance_lock());$q->execute([$entityId,shop_id()]);$source=$q->fetch();if(!$source)throw new RuntimeException('Source document unavailable.',403);
  $q=$pdo->prepare('SELECT id,request_key,content_hash FROM financial_corrections WHERE shop_id=? AND (request_key=? OR (entity_type=? AND entity_id=?))');$q->execute([shop_id(),$request,$entity,$entityId]);if($old=$q->fetch()){if($old['request_key']!==$request||!hash_equals($old['content_hash'],$hash))throw new InvalidArgumentException('Document was already corrected or request content changed.');return (int)$old['id'];}
  if($table==='expenses'&&(($source['expense_type']==='ضرر')!==($entity==='loss')))throw new InvalidArgumentException('Select the correct expense or loss category.');if($entity==='debt'&&!empty($source['sale_id']))throw new InvalidArgumentException(__t('Correct a sales invoice through sales returns.','بل فروش را از مسیر برگشت فروش اصلاح کنید.','د پلور بل د ستنولو له لارې سم کړئ.'));
  $journals=[];$types=$entity==='expense'?['expense_payable']:($entity==='loss'?['loss']:($entity==='debt'?['debt_opening']:[]));foreach($types as $type){$q=$pdo->prepare('SELECT * FROM journal_headers WHERE shop_id=? AND source_type=? AND source_id=?');$q->execute([shop_id(),$type,(string)$entityId]);$journals=array_merge($journals,$q->fetchAll());}
  $fundSources=$entity==='expense'?['expense','expense_settlement']:[$entity];$funds=[];foreach($fundSources as $type){$q=$pdo->prepare('SELECT * FROM fund_transactions WHERE shop_id=? AND source_type=? AND source_id=? ORDER BY id');$q->execute([shop_id(),$type,$entityId]);$funds=array_merge($funds,$q->fetchAll());}foreach($funds as $fund){$q=$pdo->prepare("SELECT * FROM journal_headers WHERE shop_id=? AND source_type='fund_payment' AND source_id=?");$q->execute([shop_id(),(string)$fund['id']]);$journals=array_merge($journals,$q->fetchAll());}
  if($entity==='debt'){$q=$pdo->prepare('SELECT id FROM fx_documents WHERE shop_id=? AND debt_id=?');$q->execute([shop_id(),$entityId]);if($q->fetchColumn())throw new InvalidArgumentException('An FX-settled debt needs a reviewed exchange correction, not a simple cancellation.');}
  if(!$journals&&($entity!=='debt'||dec_units($source['paid_amount'])>0))throw new InvalidArgumentException(__t('This legacy document needs a reviewed opening adjustment.','این سند قدیمی به تعدیل بررسی‌شدهٔ ماندهٔ آغاز نیاز دارد.','دا پخوانی سند تایید شوی لومړنی تعدیل غواړي.'));
  finance_seed(shop_id());$q=$pdo->prepare('SELECT closed_until FROM financial_periods WHERE shop_id=?'.finance_lock());$q->execute([shop_id()]);$closed=$q->fetchColumn();foreach($journals as $j)if(($closed&&$j['posting_date']<=$closed)||$date<$j['posting_date'])throw new InvalidArgumentException(__t('A closed-period document cannot be cancelled here; post an approved current-period adjustment.','سند دورهٔ بسته اینجا لغو نمی‌شود؛ تعدیل مجازِ دورهٔ فعلی را ثبت کنید.','د تړلې دورې سند دلته نه لغوه کېږي.'));if($closed&&$date<=$closed)throw new InvalidArgumentException('Correction period is closed.');
  $pdo->prepare('INSERT INTO financial_corrections (shop_id,entity_type,entity_id,request_key,content_hash,posting_date,reason,created_by) VALUES (?,?,?,?,?,?,?,?)')->execute([shop_id(),$entity,$entityId,$request,$hash,$date,$reason,auth_user()['id']]);$id=(int)$pdo->lastInsertId();$byCurrency=[];
  foreach($journals as $journal){$q=$pdo->prepare('SELECT account_code,debit,credit FROM journal_details WHERE journal_id=? AND shop_id=?');$q->execute([$journal['id'],shop_id()]);foreach($q->fetchAll() as $line){$c=$journal['currency_code'];$code=$line['account_code'];$byCurrency[$c][$code]=dec_add($byCurrency[$c][$code]??0,dec_sub($line['credit'],$line['debit']));}}
  foreach($byCurrency as $currency=>$balances){$lines=[];foreach($balances as $code=>$amount){if(dec_units($amount)===0)continue;$q=$pdo->prepare("SELECT id FROM fund_accounts WHERE shop_id=? AND ledger_code=?");$q->execute([shop_id(),(string)$code]);$account=(int)$q->fetchColumn();if($account){funds_account($account,$currency,true);if(dec_units($amount)<0&&dec_units(funds_available_out($account,$date))<abs(dec_units($amount)))throw new InvalidArgumentException('Cash is insufficient for this correction.');$absolute=dec_units($amount)<0?dec_mul($amount,-1):$amount;$key='financial-correction-'.$id.'-'.$account;$payload=hash('sha256',json_encode([$entity,$entityId,$account,$amount,$date],JSON_THROW_ON_ERROR));$pdo->prepare('INSERT INTO fund_transactions (shop_id,account_id,direction,amount,currency_code,payment_date,reference,source_type,source_id,request_key,content_hash,notes,created_by) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?)')->execute([shop_id(),$account,dec_units($amount)>0?'in':'out',$absolute,$currency,$date,'COR-'.$id,'correction',$id,$key,$payload,$reason,auth_user()['id']]);}$lines[]=[(string)$code,dec_units($amount)>0?$amount:0,dec_units($amount)<0?dec_mul($amount,-1):0];}if($lines)finance_post('correction',$id,$currency,$date,$reason,$lines);}
  if($entity==='loss'&&!empty($source['stock_id'])){if(!$restoreStock||$source['inventory_cost']===null)throw new InvalidArgumentException(__t('Confirm that the goods physically exist and are saleable before reversing their loss.','پیش از لغو ضایعات، موجودبودن واقعی و قابل فروش‌بودن جنس را تأیید کنید.','توکي باید په حقیقت کې موجود او د پلور وړ وي.'));$q=$pdo->prepare('SELECT * FROM stock WHERE id=? AND shop_id=?'.finance_lock());$q->execute([$source['stock_id'],shop_id()]);$stock=$q->fetch();if(!$stock||!empty($stock['partner_id'])||!empty($stock['mudaraba_id']))throw new InvalidArgumentException('Partner stock loss needs reviewed ownership adjustment.');$quantity=dec_add($stock['quantity'],$source['loss_qty'],3);$value=dec_add(inventory_value($stock),$source['inventory_cost']);$damaged=dec_sub($stock['damaged_qty']??0,$source['loss_qty'],3);if(dec_units($damaged,3)<0)$damaged='0.000';$pdo->prepare('UPDATE stock SET quantity=?,inventory_value=?,capital_amount=?,purchase_price=?,expenses=0,damaged_qty=? WHERE id=? AND shop_id=?')->execute([$quantity,$value,$value,dec_div($value,$quantity,6),$damaged,$stock['id'],shop_id()]);inventory_movement((int)$stock['id'],'loss_correction',$id,$source['loss_qty'],$source['inventory_cost'],$stock['currency_code']);}
  if($entity==='debt')$pdo->prepare("UPDATE debts SET remaining_amount=0,status='cancelled' WHERE id=? AND shop_id=?")->execute([$entityId,shop_id()]);
  domain_audit('financial_document_corrected',$entity,$entityId,['correction_id'=>$id,'reason'=>$reason,'posting_date'=>$date],null,$source);return $id;
 });
}
function finance_is_corrected(string $entity,int $id): bool {global $pdo;$q=$pdo->prepare('SELECT id FROM financial_corrections WHERE shop_id=? AND entity_type=? AND entity_id=?');$q->execute([shop_id(),$entity,$id]);return (bool)$q->fetchColumn();}
